@RunWith(MockitoJUnitRunner.class)
public class CommandLineRunner_createOptions_TriageGen2Test {

  @Spy
  private CommandLineRunner runner = new CommandLineRunner(new String[]{}, System.out, System.err);

  @Mock
  private CompilationLevel mockCompilationLevel;

  @Mock
  private WarningLevel mockWarningLevel;

  @Mock
  private FormattingOption mockFormattingOption;

  @Before
  public void setUp() {
    // Since flags is likely a protected field or accessible via internal mechanism, 
    // we assume we can manipulate the flags object of the runner.
    // In a real scenario, we access the 'flags' field of CommandLineRunner.
    runner.flags.compilation_level = mockCompilationLevel;
    runner.flags.warning_level = mockWarningLevel;
    runner.flags.debug = false;
    runner.flags.process_closure_primitives = false;
    runner.flags.formatting = Collections.emptyList();
  }

  @Test
  public void testCreateOptions_Basic() {
    // Setup
    runner.flags.compilation_level = mockCompilationLevel;
    runner.flags.warning_level = mockWarningLevel;
    runner.flags.debug = false;
    runner.flags.process_closure_primitives = true;
    runner.flags.formatting = Collections.emptyList();

    // We need to spy on the runner to avoid calling the real initOptionsFromFlags if it has side effects
    // or to ensure it doesn't crash.
    doReturn(null).when(runner).initOptionsFromFlags(org.mockito.ArgumentMatchers.any());

    // Execute
    CompilerOptions options = runner.createOptions();

    // Verify
    assertThat(options).isNotNull();
    verify(mockCompilationLevel).setOptionsForCompilationLevel(options);
    verify(mockCompilationLevel, org.mockito.Mockito.never()).setDebugOptionsForCompilationLevel(options);
    verify(mockWarningLevel).setOptionsForWarningLevel(options);
    assertThat(options.closurePass).isTrue();
  }

  @Test
  public void testCreateOptions_WithDebug() {
    // Setup
    runner.flags.compilation_level = mockCompilationLevel;
    runner.flags.warning_level = mockWarningLevel;
    runner.flags.debug = true;
    runner.flags.process_closure_primitives = false;
    runner.flags.formatting = Collections.emptyList();

    doReturn(null).when(runner).initOptionsFromFlags(org.mockito.ArgumentMatchers.any());

    // Execute
    CompilerOptions options = runner.createOptions();

    // Verify
    assertThat(options).isNotNull();
    verify(mockCompilationLevel).setOptionsForCompilationLevel(options);
    verify(mockCompilationLevel).setDebugOptionsForCompilationLevel(options);
    verify(mockWarningLevel).setOptionsForWarningLevel(options);
    assertThat(options.closurePass).isFalse();
  }

  @Test
  public void testCreateOptions_WithFormattingOptions() {
    // Setup
    runner.flags.compilation_level = mockCompilationLevel;
    runner.flags.warning_level = mockWarningLevel;
    runner.flags.debug = false;
    runner.flags.process_closure_primitives = false;
    runner.flags.formatting = Arrays.asList(mockFormattingOption);

    doReturn(null).when(runner).initOptionsFromFlags(org.mockito.ArgumentMatchers.any());

    // Execute
    CompilerOptions options = runner.createOptions();

    // Verify
    assertThat(options).isNotNull();
    verify(mockFormattingOption).applyToOptions(options);
  }

  @Test
  public void testCreateOptions_WithMultipleFormattingOptions() {
    // Setup
    FormattingOption mockFormattingOption2 = mock(FormattingOption.class);
    runner.flags.compilation_level = mockCompilationLevel;
    runner.flags.warning_level = mockWarningLevel;
    runner.flags.debug = false;
    runner.flags.process_closure_primitives = false;
    runner.flags.formatting = Arrays.asList(mockFormattingOption, mockFormattingOption2);

    doReturn(null).when(runner).initOptionsFromFlags(org.mockito.ArgumentMatchers.any());

    // Execute
    CompilerOptions options = runner.createOptions();

    // Verify
    verify(mockFormattingOption).applyToOptions(options);
    verify(mockFormattingOption2).applyToOptions(options);
  }
}
